type Props = { section: 'Execution' | 'Tracking' | 'Health' | 'Incidents' | 'Handover' | 'Notifications' | 'Route changes' | 'KPI & audit' | 'Pricing & billing'; role: string; report: (message: string) => void; notify: (message: string) => void; onOpenRequest?: (requestId: string) => void; onNotificationsChanged?: () => void };
